/**
 * Static-source preview resolution.
 *
 * ⚠️ MAVLY DOES NOT BUILD OR EXECUTE IMPORTED SOURCE. A repository is previewable
 * only when it already contains a static entry point: the standalone
 * `preview.html` generated by the agent, a root `index.html`, or a
 * `public/index.html`. A framework entry point that needs a build (Next.js,
 * Vite, CRA, …) is reported as unsupported instead of being rendered as a blank
 * success.
 */

export const GENERATED_PREVIEW_PATH = "preview.html";

export interface StaticSite {
  /** The HTML document that is served at the preview root. */
  entryPath: string;
  /** The directory its relative URLs are resolved from ("" for the repo root). */
  root: string;
  /** The agent's standalone preview, which is published as-is. */
  generated: boolean;
}

const ENTRY_CANDIDATES: readonly StaticSite[] = [
  { entryPath: GENERATED_PREVIEW_PATH, root: "", generated: true },
  { entryPath: "index.html", root: "", generated: false },
  { entryPath: "public/index.html", root: "public", generated: false },
  { entryPath: "www/index.html", root: "www", generated: false },
];

/** Pick the first known static entry point that exists in the project. */
export function resolveStaticSite(paths: readonly string[]): StaticSite | null {
  const present = new Set(paths);
  for (const candidate of ENTRY_CANDIDATES) {
    if (present.has(candidate.entryPath)) return candidate;
  }
  return null;
}

function isSafeRelativePath(value: string): boolean {
  if (!value || value.length > 512) return false;
  if (value.includes("\0") || /[\u0000-\u001f]/.test(value)) return false;
  if (value.startsWith("/") || value.includes("\\")) return false;
  return value.split("/").every((segment) => !!segment && segment !== "." && segment !== "..");
}

/**
 * Map a browser path inside the preview to a path in `project_files`.
 *
 * The empty path and `index.html` both mean the entry document. A path that
 * escapes the project or the site's root is refused; the caller answers 404.
 */
export function staticPreviewPath(site: StaticSite, requested: string): string | null {
  const clean = requested.replace(/^\/+/, "");
  if (!clean || clean === "index.html" || clean === site.entryPath) {
    return site.entryPath;
  }
  if (!isSafeRelativePath(clean)) return null;
  return site.root ? `${site.root}/${clean}` : clean;
}

export interface StaticSiteResolution {
  site: StaticSite | null;
  /** Why there is no static preview, in words the workspace can show. */
  reason: string;
  /** The source needs a build, rather than simply having no static entry yet. */
  unsupported: boolean;
}

/**
 * Resolve the preview and refuse the cases that only LOOK static.
 *
 * A Vite/CRA-style root `index.html` points at `/src/main.tsx` (or another
 * framework entry). Serving that document as-is is a blank page with a 200,
 * which is worse than saying the repository needs a build. Generated
 * `preview.html` always wins: it is already self-contained.
 */
export function resolveStaticPreview(
  files: readonly { path: string; content: string }[],
): StaticSiteResolution {
  const paths = files.map((file) => file.path);
  const site = resolveStaticSite(paths);
  if (!site) {
    return {
      site: null,
      reason:
        "This project has no static preview yet. Mavly previews preview.html, index.html, or public/index.html.",
      unsupported: false,
    };
  }
  if (site.generated) return { site, reason: "", unsupported: false };

  const entry = files.find((file) => file.path === site.entryPath);
  const html = entry?.content ?? "";
  const frameworkEntry = /<(?:script|link)\b[^>]+(?:src|href)\s*=\s*["'][^"']*(?:\/src\/|\.tsx?(?:[?#"'])|\/main\.(?:jsx?|tsx?)(?:[?#"']))/i;
  if (frameworkEntry.test(html)) {
    return {
      site: null,
      reason:
        "This repository's entry point needs a framework build (Vite, Create React App, or similar). Mavly only previews static HTML and does not build or run imported source.",
      unsupported: true,
    };
  }

  return { site, reason: "", unsupported: false };
}

/** The file path relative to the published site root, or null outside it. */
export function staticPublishPath(site: StaticSite, filePath: string): string | null {
  if (site.generated) return filePath === site.entryPath ? "index.html" : null;
  const prefix = site.root ? `${site.root}/` : "";
  if (!filePath.startsWith(prefix)) return null;
  const relative = filePath.slice(prefix.length);
  if (!isSafeRelativePath(relative)) return null;
  return relative === site.entryPath.slice(prefix.length) ? "index.html" : relative;
}

export interface StaticPublishFile {
  path: string;
  content: string;
}

/**
 * The files to upload for a deployment.
 *
 * A generated `preview.html` is standalone, so only that document is uploaded
 * (as `index.html`). An imported static site needs its sibling stylesheets,
 * scripts and images too; those are uploaded under the same relative paths and
 * the entry document becomes the site's `/index.html`.
 */
export function staticPublishFiles<T extends { path: string; content: string }>(
  files: readonly T[],
  site: StaticSite,
): StaticPublishFile[] {
  const out: StaticPublishFile[] = [];
  for (const file of files) {
    const published = staticPublishPath(site, file.path);
    if (!published) continue;
    out.push({ path: published, content: file.content });
  }
  return out.sort((a, b) => a.path.localeCompare(b.path));
}
